import {
  DeleteOutlined,
  EditOutlined,
  LogoutOutlined,
  MinusCircleOutlined,
  PlusCircleOutlined,
  PlusOutlined,
  SafetyOutlined,
  SelectOutlined,
  SwapOutlined,
} from '@ant-design/icons';
import type { ActionType, ProColumns } from '@ant-design/pro-components';
import { PageContainer, ProTable } from '@ant-design/pro-components';
import { FormattedMessage, useIntl } from '@umijs/max';
import {
  App,
  Button,
  Divider,
  Form,
  Input,
  Modal,
  Popconfirm,
  Select,
  Space,
  Switch,
} from 'antd';
import React, { useEffect, useRef, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import Settings from '../../../../config/defaultSettings';
import {
  batchForceLogout,
  batchUpdateUserStatus,
  createUser,
  deleteUser,
  forceLogoutUser,
  getAdminUserList,
  inviteUser,
  updateUser,
  updateUserSecurity,
} from '@/services/rustdesk-console/user';
import {
  getAllUserGroups,
  moveUsersToGroup,
} from '@/services/rustdesk-console/userGroup';
import { getUserColumns } from '@/components/UserSelectTable/columns';
import ImportUsersModal from './components/ImportUsersModal';

export interface UserListProps {
  userGroupGuid?: string;
  title?: string;
  onBack?: () => void;
}

const UserList: React.FC<UserListProps> = ({
  userGroupGuid,
  title,
  onBack,
}) => {
  const intl = useIntl();
  const { message: msgApi } = App.useApp();

  const actionRef = useRef<ActionType>(null);

  // Modal states
  const [createModalVisible, setCreateModalVisible] = useState(false);
  const [inviteModalVisible, setInviteModalVisible] = useState(false);
  const [editModalVisible, setEditModalVisible] = useState(false);
  const [securityModalVisible, setSecurityModalVisible] = useState(false);

  // Form instances
  const [createForm] = Form.useForm();
  const [inviteForm] = Form.useForm();
  const [editForm] = Form.useForm();
  const [securityForm] = Form.useForm();

  // Selection states (for batch operations)
  const [selectedRowKeys, setSelectedRowKeys] = useState<React.Key[]>([]);
  const [selectedRows, setSelectedRows] = useState<API.UserItem[]>([]);
  const [batchStatusUpdating, setBatchStatusUpdating] = useState(false);
  const [batchForceLoggingOut, setBatchForceLoggingOut] = useState(false);
  const [userGroups, setUserGroups] = useState<API.UserGroupItem[]>([]);
  const [userGroupsLoading, setUserGroupsLoading] = useState(false);

  // Current user being edited
  const [editingUser, setEditingUser] = useState<API.UserItem | null>(null);

  // Group member management states (only used when userGroupGuid is provided)
  const [destinationGuid, setDestinationGuid] = useState<string>();
  const [moving, setMoving] = useState(false);
  const [importModalVisible, setImportModalVisible] = useState(false);
  const [moveUser, setMoveUser] = useState<API.UserItem | null>(null);
  const [moveDestinationGuid, setMoveDestinationGuid] = useState<string>();

  useEffect(() => {
    if (!userGroupGuid) return;
    void loadUserGroups();
  }, [userGroupGuid]);

  const handleMove = async (targetGuid: string, userGuids: string[]) => {
    if (!targetGuid || userGuids.length === 0) return;
    setMoving(true);
    try {
      const result = await moveUsersToGroup(targetGuid, userGuids);
      msgApi.success(
        intl.formatMessage(
          {
            id: 'pages.userGroups.membersUpdated',
            defaultMessage: 'Updated {count} user(s)',
          },
          { count: result.moved_user_count },
        ),
      );
      setSelectedRowKeys([]);
      setSelectedRows([]);
      setDestinationGuid(undefined);
      actionRef.current?.reload();
    } catch {
      msgApi.error(
        intl.formatMessage({
          id: 'pages.userGroups.membersUpdateFailed',
          defaultMessage: 'Failed to update group members',
        }),
      );
    } finally {
      setMoving(false);
    }
  };

  const loadUserGroups = async () => {
    if (userGroups.length > 0) return userGroups;
    setUserGroupsLoading(true);
    try {
      const groups = await getAllUserGroups();
      setUserGroups(groups);
      return groups;
    } catch {
      msgApi.error(
        intl.formatMessage({
          id: 'pages.userGroups.loadFailed',
          defaultMessage: 'Failed to load user groups',
        }),
      );
      return [];
    } finally {
      setUserGroupsLoading(false);
    }
  };

  const openCreateModal = () => {
    setCreateModalVisible(true);
    void loadUserGroups().then((groups) => {
      const defaultGroup = groups.find((group) => group.is_default);
      createForm.setFieldValue('user_group_guid', defaultGroup?.guid);
    });
  };

  const openInviteModal = () => {
    setInviteModalVisible(true);
    void loadUserGroups().then((groups) => {
      const defaultGroup = groups.find((group) => group.is_default);
      inviteForm.setFieldValue('user_group_guid', defaultGroup?.guid);
    });
  };

  // Create user
  const handleCreate = async (values: API.CreateUserParams) => {
    try {
      await createUser(values);
      msgApi.success(
        intl.formatMessage({
          id: 'pages.users.createSuccess',
          defaultMessage: 'User created',
        }),
      );
      setCreateModalVisible(false);
      createForm.resetFields();
      actionRef.current?.reload();
    } catch {
      msgApi.error(
        intl.formatMessage({
          id: 'pages.users.createFailed',
          defaultMessage: 'Failed to create user',
        }),
      );
    }
  };

  // Invite user
  const handleInvite = async (values: API.InviteUserParams) => {
    try {
      await inviteUser(values);
      msgApi.success(
        intl.formatMessage({
          id: 'pages.users.inviteSuccess',
          defaultMessage: 'Invitation sent',
        }),
      );
      setInviteModalVisible(false);
      inviteForm.resetFields();
      actionRef.current?.reload();
    } catch {
      msgApi.error(
        intl.formatMessage({
          id: 'pages.users.inviteFailed',
          defaultMessage: 'Failed to send invitation',
        }),
      );
    }
  };

  // Edit user
  const handleEdit = async (values: API.UpdateUserParams) => {
    if (!editingUser) return;
    try {
      await updateUser(editingUser.guid, values);
      msgApi.success(
        intl.formatMessage({
          id: 'pages.users.updateSuccess',
          defaultMessage: 'User updated',
        }),
      );
      setEditModalVisible(false);
      setEditingUser(null);
      editForm.resetFields();
      actionRef.current?.reload();
    } catch {
      msgApi.error(
        intl.formatMessage({
          id: 'pages.users.updateFailed',
          defaultMessage: 'Failed to update user',
        }),
      );
    }
  };

  // Delete user
  const handleDelete = async (guid: string) => {
    try {
      await deleteUser(guid);
      msgApi.success(
        intl.formatMessage({
          id: 'pages.users.deleteSuccess',
          defaultMessage: 'User deleted',
        }),
      );
      actionRef.current?.reload();
    } catch {
      msgApi.error(
        intl.formatMessage({
          id: 'pages.users.deleteFailed',
          defaultMessage: 'Failed to delete user',
        }),
      );
    }
  };

  // Update single user security
  const handleUpdateSecurity = async (values: API.UpdateUserSecurityParams) => {
    if (!editingUser) return;
    try {
      await updateUserSecurity(editingUser.guid, values);
      msgApi.success(
        intl.formatMessage({
          id: 'pages.users.securityUpdateSuccess',
          defaultMessage: 'Security settings updated',
        }),
      );
      setSecurityModalVisible(false);
      setEditingUser(null);
      securityForm.resetFields();
      actionRef.current?.reload();
    } catch {
      msgApi.error(
        intl.formatMessage({
          id: 'pages.users.securityUpdateFailed',
          defaultMessage: 'Failed to update security settings',
        }),
      );
    }
  };

  // Force logout single user
  const handleForceLogout = async (guid: string) => {
    try {
      await forceLogoutUser(guid);
      msgApi.success(
        intl.formatMessage({
          id: 'pages.users.forceLogoutSuccess',
          defaultMessage: 'Force logout successful',
        }),
      );
      actionRef.current?.reload();
    } catch {
      msgApi.error(
        intl.formatMessage({
          id: 'pages.users.forceLogoutFailed',
          defaultMessage: 'Failed to force logout',
        }),
      );
    }
  };

  // Batch enable
  const handleBatchEnable = async () => {
    if (selectedRows.length === 0) return;
    setBatchStatusUpdating(true);
    try {
      const userGuids = selectedRows.map((row) => row.guid);
      const result = await batchUpdateUserStatus({
        user_guids: userGuids,
        status: 1,
      });
      if (result.failedCount > 0) {
        msgApi.warning(
          intl.formatMessage(
            {
              id: 'pages.users.batchEnablePartialFailed',
              defaultMessage:
                'Successfully enabled {success} user(s), {failed} failed',
            },
            { success: result.succeededCount, failed: result.failedCount },
          ),
        );
      } else {
        msgApi.success(
          intl.formatMessage(
            {
              id: 'pages.users.batchEnableSuccess',
              defaultMessage: 'Successfully enabled {count} user(s)',
            },
            { count: result.succeededCount },
          ),
        );
      }
      setSelectedRowKeys([]);
      setSelectedRows([]);
      actionRef.current?.reload();
    } catch {
      msgApi.error(
        intl.formatMessage({
          id: 'pages.users.batchEnableFailed',
          defaultMessage: 'Failed to enable users',
        }),
      );
    } finally {
      setBatchStatusUpdating(false);
    }
  };

  // Batch disable
  const handleBatchDisable = async () => {
    if (selectedRows.length === 0) return;
    setBatchStatusUpdating(true);
    try {
      const userGuids = selectedRows.map((row) => row.guid);
      const result = await batchUpdateUserStatus({
        user_guids: userGuids,
        status: 0,
      });
      if (result.failedCount > 0) {
        msgApi.warning(
          intl.formatMessage(
            {
              id: 'pages.users.batchDisablePartialFailed',
              defaultMessage:
                'Successfully disabled {success} user(s), {failed} failed',
            },
            { success: result.succeededCount, failed: result.failedCount },
          ),
        );
      } else {
        msgApi.success(
          intl.formatMessage(
            {
              id: 'pages.users.batchDisableSuccess',
              defaultMessage: 'Successfully disabled {count} user(s)',
            },
            { count: result.succeededCount },
          ),
        );
      }
      setSelectedRowKeys([]);
      setSelectedRows([]);
      actionRef.current?.reload();
    } catch {
      msgApi.error(
        intl.formatMessage({
          id: 'pages.users.batchDisableFailed',
          defaultMessage: 'Failed to disable users',
        }),
      );
    } finally {
      setBatchStatusUpdating(false);
    }
  };

  // Batch force logout
  const handleBatchForceLogout = async () => {
    if (selectedRows.length === 0) return;
    setBatchForceLoggingOut(true);
    try {
      const userGuids = selectedRows.map((row) => row.guid);
      await batchForceLogout({ user_guids: userGuids });
      msgApi.success(
        intl.formatMessage({
          id: 'pages.users.batchForceLogoutSuccess',
          defaultMessage: 'Force logout successful',
        }),
      );
      setSelectedRowKeys([]);
      setSelectedRows([]);
      actionRef.current?.reload();
    } catch {
      msgApi.error(
        intl.formatMessage({
          id: 'pages.users.batchForceLogoutFailed',
          defaultMessage: 'Failed to force logout',
        }),
      );
    } finally {
      setBatchForceLoggingOut(false);
    }
  };

  // Open edit modal
  const openEditModal = (record: API.UserItem) => {
    setEditingUser(record);
    void loadUserGroups();
    editForm.setFieldsValue({
      name: record.name,
      display_name: record.display_name,
      email: record.email,
      note: record.note,
      status: record.status,
      is_admin: record.is_admin,
      user_group_guid: record.user_group_guid,
    });
    setEditModalVisible(true);
  };

  // Open security modal
  const openSecurityModal = (record: API.UserItem) => {
    setEditingUser(record);
    securityForm.resetFields();
    setSecurityModalVisible(true);
  };

  const baseColumns = getUserColumns();

  const actionColumn: ProColumns<API.UserItem> = {
    title: (
      <FormattedMessage id="pages.common.action" defaultMessage="Action" />
    ),
    valueType: 'option',
    width: 220,
    fixed: 'right',
    render: (_: unknown, record: API.UserItem) =>
      userGroupGuid ? (
        <Button
          type="link"
          size="small"
          icon={<SwapOutlined />}
          onClick={() => {
            setMoveUser(record);
            setMoveDestinationGuid(undefined);
          }}
        >
          <FormattedMessage id="pages.userGroups.move" defaultMessage="Move" />
        </Button>
      ) : (
        <Space size={0} split={<Divider type="vertical" />}>
          <Button
            key="edit"
            type="link"
            size="small"
            icon={<EditOutlined />}
            onClick={() => openEditModal(record)}
          >
            <FormattedMessage id="pages.common.edit" defaultMessage="Edit" />
          </Button>
          <Button
            key="security"
            type="link"
            size="small"
            icon={<SafetyOutlined />}
            onClick={() => openSecurityModal(record)}
          >
            <FormattedMessage
              id="pages.users.security"
              defaultMessage="Security"
            />
          </Button>
          <Button
            key="logout"
            type="link"
            size="small"
            icon={<LogoutOutlined />}
            onClick={() => handleForceLogout(record.guid)}
          >
            <FormattedMessage
              id="pages.users.forceLogout"
              defaultMessage="Logout"
            />
          </Button>
          <Popconfirm
            key="delete"
            title={
              <FormattedMessage
                id="pages.users.deleteConfirm"
                defaultMessage="Are you sure to delete this user?"
              />
            }
            onConfirm={() => handleDelete(record.guid)}
            okText={intl.formatMessage({
              id: 'pages.common.confirm',
              defaultMessage: 'Yes',
            })}
            cancelText={intl.formatMessage({
              id: 'pages.common.cancel',
              defaultMessage: 'No',
            })}
          >
            <Button type="link" size="small" danger icon={<DeleteOutlined />}>
              <FormattedMessage
                id="pages.common.delete"
                defaultMessage="Delete"
              />
            </Button>
          </Popconfirm>
        </Space>
      ),
  };

  const columns = [...baseColumns, actionColumn];

  return (
    <>
      {title && (
        <Helmet>
          <title>
            {title}
            {Settings.title && ` - ${Settings.title}`}
          </title>
        </Helmet>
      )}
      <PageContainer
        title={
          title || (
            <FormattedMessage
              id="pages.users.list"
              defaultMessage="User List"
            />
          )
        }
        onBack={onBack}
      >
        <ProTable<API.UserItem>
          headerTitle={
            <FormattedMessage
              id="pages.users.list"
              defaultMessage="User List"
            />
          }
          columnsState={{
            persistenceType: 'localStorage',
            persistenceKey: 'user_list_columns_state',
          }}
          actionRef={actionRef}
          rowKey="guid"
          rowSelection={{
            selectedRowKeys,
            onChange: (keys, rows) => {
              setSelectedRowKeys(keys);
              setSelectedRows(rows);
            },
          }}
          tableAlertOptionRender={() =>
            userGroupGuid ? (
              <Space size={16}>
                <Select
                  aria-label={intl.formatMessage({
                    id: 'pages.userGroups.destination',
                    defaultMessage: 'Destination group',
                  })}
                  showSearch
                  optionFilterProp="label"
                  loading={userGroupsLoading}
                  value={destinationGuid}
                  onChange={setDestinationGuid}
                  placeholder={intl.formatMessage({
                    id: 'pages.userGroups.selectDestination',
                    defaultMessage: 'Select destination group',
                  })}
                  options={userGroups
                    .filter((g) => g.guid !== userGroupGuid)
                    .map((g) => ({ label: g.name, value: g.guid }))}
                  style={{ width: 200 }}
                />
                <Button
                  type="link"
                  icon={<SwapOutlined />}
                  disabled={!destinationGuid || selectedRows.length === 0}
                  loading={moving}
                  onClick={() =>
                    destinationGuid &&
                    handleMove(
                      destinationGuid,
                      selectedRows.map((r) => r.guid),
                    )
                  }
                  style={{ padding: 0 }}
                >
                  <FormattedMessage
                    id="pages.userGroups.batchMove"
                    defaultMessage="Batch Move"
                  />
                </Button>
              </Space>
            ) : (
              <Space size={16}>
                <Popconfirm
                  title={
                    <FormattedMessage
                      id="pages.users.batchEnableConfirm"
                      defaultMessage="Are you sure to enable selected users?"
                    />
                  }
                  onConfirm={handleBatchEnable}
                  okText={intl.formatMessage({
                    id: 'pages.common.confirm',
                    defaultMessage: 'Yes',
                  })}
                  cancelText={intl.formatMessage({
                    id: 'pages.common.cancel',
                    defaultMessage: 'No',
                  })}
                >
                  <Button
                    type="link"
                    icon={<PlusCircleOutlined />}
                    loading={batchStatusUpdating}
                    style={{ padding: 0 }}
                  >
                    <FormattedMessage
                      id="pages.users.batchEnable"
                      defaultMessage="Batch Enable"
                    />
                  </Button>
                </Popconfirm>
                <Popconfirm
                  title={
                    <FormattedMessage
                      id="pages.users.batchDisableConfirm"
                      defaultMessage="Are you sure to disable selected users?"
                    />
                  }
                  onConfirm={handleBatchDisable}
                  okText={intl.formatMessage({
                    id: 'pages.common.confirm',
                    defaultMessage: 'Yes',
                  })}
                  cancelText={intl.formatMessage({
                    id: 'pages.common.cancel',
                    defaultMessage: 'No',
                  })}
                >
                  <Button
                    type="link"
                    icon={<MinusCircleOutlined />}
                    loading={batchStatusUpdating}
                    style={{ padding: 0 }}
                  >
                    <FormattedMessage
                      id="pages.users.batchDisable"
                      defaultMessage="Batch Disable"
                    />
                  </Button>
                </Popconfirm>
                <Popconfirm
                  title={
                    <FormattedMessage
                      id="pages.users.batchForceLogoutConfirm"
                      defaultMessage="Are you sure to force logout selected users?"
                    />
                  }
                  onConfirm={handleBatchForceLogout}
                  okText={intl.formatMessage({
                    id: 'pages.common.confirm',
                    defaultMessage: 'Yes',
                  })}
                  cancelText={intl.formatMessage({
                    id: 'pages.common.cancel',
                    defaultMessage: 'No',
                  })}
                >
                  <Button
                    type="link"
                    icon={<LogoutOutlined />}
                    loading={batchForceLoggingOut}
                    style={{ padding: 0 }}
                  >
                    <FormattedMessage
                      id="pages.users.batchForceLogout"
                      defaultMessage="Batch Force Logout"
                    />
                  </Button>
                </Popconfirm>
              </Space>
            )
          }
          request={async (params) => {
            const result = await getAdminUserList({
              current: params.current || 1,
              pageSize: params.pageSize || 20,
              status: params.status,
              name: params.name,
              email: params.email,
              is_admin:
                params.is_admin === 'true'
                  ? 1
                  : params.is_admin === 'false'
                    ? 0
                    : undefined,
              user_group_guid: userGroupGuid,
            });
            return {
              data: result.data || [],
              total: result.total || 0,
              success: true,
            };
          }}
          columns={
            userGroupGuid
              ? columns.filter((col) => col.dataIndex !== 'user_group_name')
              : columns
          }
          search={{
            labelWidth: 'auto',
            defaultCollapsed: true,
            optionRender: (_searchConfig, _formProps, dom) => [
              ...dom.reverse(),
            ],
          }}
          pagination={{
            defaultPageSize: 20,
            showSizeChanger: true,
            showQuickJumper: true,
          }}
          scroll={{ x: 1540 }}
          toolBarRender={() =>
            userGroupGuid
              ? [
                  <Button
                    key="import"
                    icon={<SelectOutlined />}
                    onClick={() => setImportModalVisible(true)}
                  >
                    <FormattedMessage
                      id="pages.userGroups.import"
                      defaultMessage="Import"
                    />
                  </Button>,
                ]
              : [
                  <Button
                    key="create"
                    type="primary"
                    icon={<PlusOutlined />}
                    onClick={openCreateModal}
                  >
                    <FormattedMessage
                      id="pages.users.create"
                      defaultMessage="Create"
                    />
                  </Button>,
                  <Button
                    key="invite"
                    icon={<PlusOutlined />}
                    onClick={openInviteModal}
                  >
                    <FormattedMessage
                      id="pages.users.invite"
                      defaultMessage="Invite"
                    />
                  </Button>,
                ]
          }
          options={{
            density: true,
            setting: {
              listsHeight: 400,
            },
            fullScreen: false,
            reload: true,
          }}
        />

        {/* Create User Modal */}
        <Modal
          title={
            <FormattedMessage
              id="pages.users.create"
              defaultMessage="Create User"
            />
          }
          open={createModalVisible}
          onCancel={() => setCreateModalVisible(false)}
          onOk={() => createForm.submit()}
        >
          <Form form={createForm} onFinish={handleCreate} layout="vertical">
            <Form.Item
              name="name"
              label={
                <FormattedMessage
                  id="pages.users.name"
                  defaultMessage="Username"
                />
              }
              rules={[
                {
                  required: true,
                  message: intl.formatMessage({
                    id: 'pages.common.pleaseEnterUsername',
                    defaultMessage: 'Please enter username',
                  }),
                },
              ]}
            >
              <Input />
            </Form.Item>
            <Form.Item
              name="display_name"
              label={
                <FormattedMessage
                  id="pages.users.displayName"
                  defaultMessage="Display Name"
                />
              }
            >
              <Input />
            </Form.Item>
            <Form.Item
              name="password"
              label={
                <FormattedMessage
                  id="pages.users.password"
                  defaultMessage="Password"
                />
              }
              rules={[
                {
                  required: true,
                  message: intl.formatMessage({
                    id: 'pages.common.pleaseEnterPassword',
                    defaultMessage: 'Please enter password',
                  }),
                },
              ]}
            >
              <Input.Password />
            </Form.Item>
            <Form.Item
              name="email"
              label={
                <FormattedMessage
                  id="pages.users.email"
                  defaultMessage="Email"
                />
              }
              rules={[
                {
                  type: 'email',
                  message: intl.formatMessage({
                    id: 'pages.common.pleaseEnterValidEmail',
                    defaultMessage: 'Please enter valid email',
                  }),
                },
              ]}
            >
              <Input />
            </Form.Item>
            <Form.Item
              name="note"
              label={
                <FormattedMessage id="pages.users.note" defaultMessage="Note" />
              }
            >
              <Input.TextArea />
            </Form.Item>
            <Form.Item
              name="user_group_guid"
              label={
                <FormattedMessage
                  id="pages.users.userGroup"
                  defaultMessage="User Group"
                />
              }
            >
              <Select
                allowClear
                showSearch
                optionFilterProp="label"
                loading={userGroupsLoading}
                placeholder={intl.formatMessage({
                  id: 'pages.users.selectUserGroup',
                  defaultMessage: 'Select user group',
                })}
                options={userGroups.map((group) => ({
                  label: group.name,
                  value: group.guid,
                }))}
              />
            </Form.Item>
          </Form>
        </Modal>

        {/* Invite User Modal */}
        <Modal
          title={
            <FormattedMessage
              id="pages.users.invite"
              defaultMessage="Invite User"
            />
          }
          open={inviteModalVisible}
          onCancel={() => setInviteModalVisible(false)}
          onOk={() => inviteForm.submit()}
        >
          <Form form={inviteForm} onFinish={handleInvite} layout="vertical">
            <Form.Item
              name="name"
              label={
                <FormattedMessage
                  id="pages.users.name"
                  defaultMessage="Username"
                />
              }
              rules={[
                {
                  required: true,
                  message: intl.formatMessage({
                    id: 'pages.common.pleaseEnterUsername',
                    defaultMessage: 'Please enter username',
                  }),
                },
              ]}
            >
              <Input />
            </Form.Item>
            <Form.Item
              name="display_name"
              label={
                <FormattedMessage
                  id="pages.users.displayName"
                  defaultMessage="Display Name"
                />
              }
            >
              <Input />
            </Form.Item>
            <Form.Item
              name="email"
              label={
                <FormattedMessage
                  id="pages.users.email"
                  defaultMessage="Email"
                />
              }
              rules={[
                {
                  required: true,
                  message: intl.formatMessage({
                    id: 'pages.common.pleaseEnterEmail',
                    defaultMessage: 'Please enter email',
                  }),
                },
                {
                  type: 'email',
                  message: intl.formatMessage({
                    id: 'pages.common.pleaseEnterValidEmail',
                    defaultMessage: 'Please enter valid email',
                  }),
                },
              ]}
            >
              <Input />
            </Form.Item>
            <Form.Item
              name="note"
              label={
                <FormattedMessage id="pages.users.note" defaultMessage="Note" />
              }
            >
              <Input.TextArea />
            </Form.Item>
            <Form.Item
              name="user_group_guid"
              label={
                <FormattedMessage
                  id="pages.users.userGroup"
                  defaultMessage="User Group"
                />
              }
            >
              <Select
                allowClear
                showSearch
                optionFilterProp="label"
                loading={userGroupsLoading}
                placeholder={intl.formatMessage({
                  id: 'pages.users.selectUserGroup',
                  defaultMessage: 'Select user group',
                })}
                options={userGroups.map((group) => ({
                  label: group.name,
                  value: group.guid,
                }))}
              />
            </Form.Item>
          </Form>
        </Modal>

        {/* Edit User Modal */}
        <Modal
          title={
            <FormattedMessage
              id="pages.users.edit"
              defaultMessage="Edit User"
            />
          }
          open={editModalVisible}
          onCancel={() => {
            setEditModalVisible(false);
            setEditingUser(null);
            editForm.resetFields();
          }}
          onOk={() => editForm.submit()}
        >
          <Form form={editForm} onFinish={handleEdit} layout="vertical">
            <Form.Item
              name="name"
              label={
                <FormattedMessage
                  id="pages.users.name"
                  defaultMessage="Username"
                />
              }
              rules={[
                {
                  required: true,
                  message: intl.formatMessage({
                    id: 'pages.common.pleaseEnterUsername',
                    defaultMessage: 'Please enter username',
                  }),
                },
              ]}
            >
              <Input />
            </Form.Item>
            <Form.Item
              name="display_name"
              label={
                <FormattedMessage
                  id="pages.users.displayName"
                  defaultMessage="Display Name"
                />
              }
            >
              <Input />
            </Form.Item>
            <Form.Item
              name="email"
              label={
                <FormattedMessage
                  id="pages.users.email"
                  defaultMessage="Email"
                />
              }
              rules={[
                {
                  type: 'email',
                  message: intl.formatMessage({
                    id: 'pages.common.pleaseEnterValidEmail',
                    defaultMessage: 'Please enter valid email',
                  }),
                },
              ]}
            >
              <Input />
            </Form.Item>
            <Form.Item
              name="note"
              label={
                <FormattedMessage id="pages.users.note" defaultMessage="Note" />
              }
            >
              <Input.TextArea />
            </Form.Item>
            <Form.Item
              name="status"
              label={
                <FormattedMessage
                  id="pages.users.status"
                  defaultMessage="Status"
                />
              }
            >
              <Select
                options={[
                  {
                    label: intl.formatMessage({
                      id: 'pages.users.active',
                      defaultMessage: 'Active',
                    }),
                    value: 1,
                  },
                  {
                    label: intl.formatMessage({
                      id: 'pages.users.disabled',
                      defaultMessage: 'Disabled',
                    }),
                    value: 0,
                  },
                  {
                    label: intl.formatMessage({
                      id: 'pages.users.unverified',
                      defaultMessage: 'Unverified',
                    }),
                    value: -1,
                  },
                ]}
              />
            </Form.Item>
            <Form.Item
              name="user_group_guid"
              label={
                <FormattedMessage
                  id="pages.users.userGroup"
                  defaultMessage="User Group"
                />
              }
            >
              <Select
                allowClear
                showSearch
                optionFilterProp="label"
                loading={userGroupsLoading}
                placeholder={intl.formatMessage({
                  id: 'pages.users.selectUserGroup',
                  defaultMessage: 'Select user group',
                })}
                options={userGroups.map((group) => ({
                  label: group.name,
                  value: group.guid,
                }))}
              />
            </Form.Item>
            <Form.Item
              name="is_admin"
              label={
                <FormattedMessage
                  id="pages.users.isAdmin"
                  defaultMessage="Admin"
                />
              }
              valuePropName="checked"
            >
              <Switch />
            </Form.Item>
          </Form>
        </Modal>

        {/* Security Settings Modal */}
        <Modal
          title={
            <FormattedMessage
              id="pages.users.securitySettings"
              defaultMessage="Security Settings"
            />
          }
          open={securityModalVisible}
          onCancel={() => {
            setSecurityModalVisible(false);
            setEditingUser(null);
            securityForm.resetFields();
          }}
          onOk={() => securityForm.submit()}
        >
          <Form
            form={securityForm}
            onFinish={handleUpdateSecurity}
            layout="vertical"
          >
            <Form.Item
              name="tfa_enforce"
              label={
                <FormattedMessage
                  id="pages.users.tfaEnforce"
                  defaultMessage="Enforce Two-Factor Authentication"
                />
              }
              valuePropName="checked"
            >
              <Switch />
            </Form.Item>
            <Form.Item
              name="email_verification"
              label={
                <FormattedMessage
                  id="pages.users.emailVerification"
                  defaultMessage="Require Email Verification"
                />
              }
              valuePropName="checked"
            >
              <Switch />
            </Form.Item>
          </Form>
        </Modal>

        {userGroupGuid && (
          <ImportUsersModal
            open={importModalVisible}
            userGroupGuid={userGroupGuid}
            onCancel={() => setImportModalVisible(false)}
            onSuccess={() => actionRef.current?.reload()}
          />
        )}

        <Modal
          title={
            <FormattedMessage
              id="pages.userGroups.moveToGroup"
              defaultMessage="Move to group"
            />
          }
          open={!!moveUser}
          onCancel={() => {
            setMoveUser(null);
            setMoveDestinationGuid(undefined);
          }}
          onOk={() => {
            if (moveUser && moveDestinationGuid) {
              void handleMove(moveDestinationGuid, [moveUser.guid]);
              setMoveUser(null);
              setMoveDestinationGuid(undefined);
            }
          }}
          okButtonProps={{ disabled: !moveDestinationGuid }}
          destroyOnHidden
        >
          <Select
            showSearch
            optionFilterProp="label"
            style={{ width: '100%' }}
            loading={userGroupsLoading}
            value={moveDestinationGuid}
            onChange={setMoveDestinationGuid}
            placeholder={intl.formatMessage({
              id: 'pages.userGroups.selectDestination',
              defaultMessage: 'Select destination group',
            })}
            options={userGroups
              .filter((g) => g.guid !== userGroupGuid)
              .map((g) => ({ label: g.name, value: g.guid }))}
          />
        </Modal>
      </PageContainer>
    </>
  );
};

export default UserList;
